import pandas as pd,numpy as np
from scipy.signal import lfilter
from scipy.optimize import least_squares
def lp(x,T,dt,x0):
    a=np.exp(-dt/max(T,1e-5))
    y,_=lfilter([1-a],[1,-a],x,zi=[a*x0]); return y
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_load_op2.csv','train/A_gentrip_op1.csv']
D=[pd.read_csv(f) for f in files]
def simQ(p,d,kind):
    t=d.time_s.values; dt=t[1]-t[0]
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q0=d.reactive_power_pu.values[0]; V0=V[0]; Vs0=Vs[0]
    if kind=='lag':
        Kvs,Kv,Tq,Tm=p
        Vm=lp(V,Tm,dt,V0)
        return Q0+lp(Kvs*(Vs-Vs0)-Kv*(Vm-V0),Tq,dt,0.0)
    if kind=='pi':
        Kvs,Kv,Ki,Tm=p
        Vm=lp(V,Tm,dt,V0)
        e=Vs-Vm
        # integrator x' = Ki*e ; Q = Q0+Kvs*(Vs-Vs0)-Kv*(Vm-V0)+x  (Euler, vectorized via cumsum)
        x=np.concatenate([[0],np.cumsum(Ki*e[:-1]*dt)])
        return Q0+Kvs*(Vs-Vs0)-Kv*(Vm-V0)+x
def res(p,kind):
    return np.concatenate([simQ(p,d,kind)-d.reactive_power_pu.values for d in D])
for kind,p0,lb,ub in [('lag',[2,2,0.1,0.01],[-50,-50,1e-3,1e-4],[50,50,10,1]),('pi',[2,2,1,0.01],[-50,-50,-100,1e-4],[50,50,100,1])]:
    s=least_squares(res,p0,args=(kind,),bounds=(lb,ub))
    print(kind,s.x.round(4),'rms',np.sqrt(np.mean(s.fun**2)).round(5))
    for d in D:
        print('   ',np.sqrt(np.mean((simQ(s.x,d,kind)-d.reactive_power_pu.values)**2)).round(5))

